let active=events[0],filter='all'; const days=document.querySelector('#days'),detail=document.querySelector('#detail');
function renderDays(){days.innerHTML='';for(let i=0;i<35;i++){let day=i-6;let box=document.createElement('div');box.className='day'+(day<1||day>30?' muted':'');box.innerHTML=`<span class="date">${day<1?31+day:day>30?day-30:day}</span>`;events.filter(e=>e.d===day&&(filter==='all'||e.cat===filter)).forEach(e=>{let b=document.createElement('button');b.className='event '+(e.cat==='major'?'major':'');b.innerHTML=`${e.p}<span>${e.n}</span>`;b.onclick=()=>{active=e;renderDetail();document.querySelectorAll('.event').forEach(x=>x.classList.remove('focus'));b.classList.add('focus')};box.append(b)});days.append(box)}}
function renderDetail(){let f=active.fights;detail.innerHTML=`<div class="detail-tag">${active.p} · ${active.cat==='major'?'MAJOR PROMOTION':'EVENT'}</div><h2>${active.n}</h2><div class="detail-date">11월 ${active.d}일 · ${active.city}</div><div class="poster"><small>OFFICIAL POSTER AREA<br>API / CMS ASSET</small></div><div class="info"><div><b>현지 시작</b>${active.zone}</div><div><b>한국 시간</b>${active.kst}</div><div><b>개최 장소</b>${active.venue}</div><div><b>시청</b>${active.watch}</div></div><div class="map"><i class="pin"></i><span class="map-label">${active.city}</span></div><h3 class="card-heading">FIGHT CARD <small>· 공식 카드 연동</small></h3>${[[f[0],f[1]],[f[2],f[3]]].map((pair,i)=>`<div class="fight"><i class="fighter-pic"></i><div>${pair[0][0]}<span>${pair[0][1]}</span></div><strong>${i?'CO-MAIN':'MAIN'}<br>VS</strong><div style="text-align:right">${pair[1][0]}<span>${pair[1][1]}</span></div></div>`).join('')}<div class="links"><a href="#">공식 홈페이지</a><a href="#">티켓 / PPV</a></div>`}
document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelector('.filter.selected').classList.remove('selected');b.classList.add('selected');renderDays()});
document.querySelector('#prev').onclick=()=>alert('연·월 선택 및 과거 일정 아카이브는 데이터 API 연결 후 활성화됩니다.');document.querySelector('#next').onclick=()=>alert('다음 달 일정 데이터는 API 연결 후 자동으로 채워집니다.');renderDays();renderDetail();
function calendarUrl(){const start=`202611${String(active.d).padStart(2,'0')}T120000Z`,end=`202611${String(active.d).padStart(2,'0')}T160000Z`;return `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(active.p+' — '+active.n)}&dates=${start}/${end}&location=${encodeURIComponent(active.venue+', '+active.city)}&details=${encodeURIComponent('OCTAGON ATLAS 일정 · '+active.watch)}`}
document.querySelector('#googleCal').onclick=()=>window.open(calendarUrl(),'_blank','noopener');
document.querySelector('#appleCal').onclick=()=>{window.location.href='calendar.ics'};
